  const AGUJEROS = [{ x: 957, y0: 432, y1: 492 }, { x: 1062, y0: 432, y1: 492 }];   // los de la pared del pasillo del medio
  const PUAS = { x0: 1146, y0: 356, x1: 1187, y1: 418, cols: [1154, 1166, 1178], filas: [366, 378, 390, 402, 413] };
