      a.talkers.push({ x: 300, y: 470, r: 44, lines: ['Zarpazos en la roca, hondos como surcos. Acá adentro manda él'] });
      a.talkers.push({ x: LUGAR.calaveras.x, y: LUGAR.calaveras.y + 40, r: 52, lines: ['Calaveras de orcos, de lobos, de hombres… La manada guarda acá lo que caza'] });
      a.talkers.push({ x: LUGAR.cazadores.x, y: LUGAR.cazadores.y, r: 54, lines: ['Los cazadores orcos que bajaron hasta acá: el techo se les vino encima y la manada hizo el resto'] });
      a.talkers.push({ x: 768, y: 262, r: 30, lines: ['Dos losas flojas en el piso, y arriba un agujero en la pared. Mejor no pisarlas'] });
