    for (let i = 0; i < 4; i++) S.time.delayedCall(i * 300, () => polvo(S, a.x + LUGAR.rocas.x + (Math.random() - 0.5) * 80, a.y + LUGAR.rocas.y - 10, 7, 0x7a7068));
